import{c as t,Q as a,j as o,m as s}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"First Launch","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/first-launch.md","filePath":"getting-started/first-launch.md","lastUpdated":null}'),r={name:"getting-started/first-launch.md"};function i(n,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h1><p>After <code>docker compose up -d</code>, open <code>http://localhost:8674</code> on the Docker host.</p><h2 id="the-setup-wizard" tabindex="-1">The setup wizard <a class="header-anchor" href="#the-setup-wizard" aria-label="Permalink to &quot;The setup wizard&quot;">​</a></h2><ol><li>Pick a username and a password (≥10 characters).</li><li>The server generates a <strong>recovery key</strong> — a printable, high-entropy secret that wraps your database key alongside your password.</li><li>The wizard shows the key once. Save it before continuing — it is the only way back after a lost password. Recovery resets the password, rotates the key, and revokes existing sessions.</li></ol><p>The first account is the sole administrator. Use <strong>Settings → Account → Manage users</strong> to add household members. Each gets an isolated <code>users/&lt;uuid&gt;/data.sqlcipher</code> and a one-time key you must deliver securely. Deleting a user removes their entire <code>users/&lt;uuid&gt;/</code> directory and revokes their sessions.</p><h2 id="cookies-and-https" tabindex="-1">Cookies and HTTPS <a class="header-anchor" href="#cookies-and-https" aria-label="Permalink to &quot;Cookies and HTTPS&quot;">​</a></h2><p><code>FINSIGHT_COOKIE_SECURE=1</code> is the default (and the correct value behind HTTPS). The cookie is <code>HttpOnly</code>, <code>SameSite=Lax</code>, 30-day sliding lifetime, persisted via <code>/data/session.key</code> — logout and recovery revoke it.</p><p>For a local smoke test <code>http://localhost:8674</code> works without override: browsers treat <code>localhost</code> as a secure context.</p><p>For bare <code>http://&lt;lan-ip&gt;:8674</code> from another device, temporarily set:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  FINSIGHT_COOKIE_SECURE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # LAN testing only — revert to 1 before HTTPS</span></span></code></pre></div><p>Revert to <code>1</code> before putting FinSight behind a proxy. Never leave <code>0</code> on anything reachable beyond your LAN.</p><h2 id="what-needs-a-secure-context" tabindex="-1">What needs a secure context <a class="header-anchor" href="#what-needs-a-secure-context" aria-label="Permalink to &quot;What needs a secure context&quot;">​</a></h2><p>Without HTTPS (or <code>localhost</code>), three features are quietly inert — no error, they just do not happen:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Without HTTPS</th></tr></thead><tbody><tr><td>Installable PWA + offline shell</td><td>Service worker does not register</td></tr><tr><td>Encrypted offline cache</td><td><code>crypto.subtle</code> unavailable → cache is not written at all; data is never stored in the clear</td></tr><tr><td>Share-target import, Web Push, badges</td><td>Depend on the worker above</td></tr></tbody></table><p>Browsing over <code>http://&lt;lan-ip&gt;:8674</code> still works as a plain web app; you just lose the installed experience. See <a href="/FinSight/help/self-hosting">Self-Hosting</a> for Tailscale, Caddy, and LAN recipes.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><strong>Onboarding</strong> walks you through accounts — manual or SimpleFIN — and an optional CSV import.</li><li><strong>Settings → Data &amp; backups</strong> handles encrypted snapshots. For disaster recovery, also back up the whole <code>/data</code> volume so <code>users.db</code> and every per-user database stay together.</li></ul><p>Next: <a href="/FinSight/getting-started/onboarding">Onboarding</a>.</p>`,18)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
